func DoneRecordLoadMessages(values []DoneRecord, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !DoneRecordLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ---- THE FIXED FORM, form byte 3 (docs/SPEC-TABLES.md §3.4) ----
//
// A record is an eight-byte hash of the writer's layout and then the values
// in declared order, every field at its declared storage width. The writer is
// constant-offset stores; the reader is ONE loop over ONE plan.

func CompletionFixedLeaves(out []TableFixedEntry, links [][]TableFixedGuardLink, src, dst uint32) int {
	n := 0
	out[n] = TableFixedEntry{Src: src + 0, Dst: dst + uint32(unsafe.Offsetof(Completion{}.KindLength)), Size: 16, Aux: dst + uint32(unsafe.Offsetof(Completion{}.Kind)), Guard: tableFixedNoGuard, Op: tableFixedText, Meta: 1} // kind
	n++
	out[n] = TableFixedEntry{Src: src + 20, Dst: dst + uint32(unsafe.Offsetof(Completion{}.CardLength)), Size: 515, Aux: dst + uint32(unsafe.Offsetof(Completion{}.Card)), Guard: tableFixedNoGuard, Op: tableFixedText, Meta: 1} // card
	n++
	out[n] = TableFixedEntry{Src: src + 539, Dst: dst + uint32(unsafe.Offsetof(Completion{}.RowLength)), Size: 135, Aux: dst + uint32(unsafe.Offsetof(Completion{}.Row)), Guard: tableFixedNoGuard, Op: tableFixedText, Meta: 1} // row
	n++
	{
		es := src + 678
		ed := dst + uint32(unsafe.Offsetof(Completion{}.At))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	return n
}

func CompletionFixedWriteBody(b []byte, value *Completion) {
	tableFixedPut32(b[0:], uint32(value.KindLength))
	copy(b[0:][4:], value.Kind[:])
	tableFixedPut32(b[20:], uint32(value.CardLength))
	copy(b[20:][4:], value.Card[:])
	tableFixedPut32(b[539:], uint32(value.RowLength))
	copy(b[539:][4:], value.Row[:])
	tableFixedPut64(b[678:], uint64(value.At))
}

func DoneRecordFixedLeaves(out []TableFixedEntry, links [][]TableFixedGuardLink, src, dst uint32) int {
	n := 0
	{
		es := src + 0
		ed := dst + uint32(unsafe.Offsetof(DoneRecord{}.Epoch))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	out[n] = TableFixedEntry{Src: src + 8, Dst: dst + uint32(unsafe.Offsetof(DoneRecord{}.CursorLength)), Size: 41, Aux: dst + uint32(unsafe.Offsetof(DoneRecord{}.Cursor)), Guard: tableFixedNoGuard, Op: tableFixedText, Meta: 1} // cursor
	n++
	out[n] = TableFixedEntry{Src: src + 53, Dst: dst + uint32(unsafe.Offsetof(DoneRecord{}.DoneCount)), Size: 95, Guard: tableFixedNoGuard, Op: tableFixedCount} // done count
	n++
	for i := uint32(0); i < 95; i++ {
		es := src + 57 + i*686
		ed := dst + uint32(unsafe.Offsetof(DoneRecord{}.Done)) + i*uint32(unsafe.Sizeof(Completion{}))
		n += CompletionFixedLeaves(out[n:], links[n:], es, ed)
	}
	return n
}

func DoneRecordFixedWriteBody(b []byte, value *DoneRecord) {
	tableFixedPut64(b[0:], uint64(value.Epoch))
	tableFixedPut32(b[8:], uint32(value.CursorLength))
	copy(b[8:][4:], value.Cursor[:])
	tableFixedPut32(b[53:], uint32(value.DoneCount))
	for i := int64(0); i < 95; i++ {
		CompletionFixedWriteBody(b[57:][i*686:], &value.Done[i])
	}
}

// Completion's read-side bounds.
func CompletionFixedClampBody(value *Completion, clamped *int32) {
	_, _ = value, clamped
}

// DoneRecord's read-side bounds.
func DoneRecordFixedClampBody(value *DoneRecord, clamped *int32) {
	_, _ = value, clamped
	for i := int64(0); i < int64(value.DoneCount); i++ {
		CompletionFixedClampBody(&value.Done[i], clamped)
	}
}

// THE READ-SIDE BOUNDS (docs/SPEC-TABLES.md §3.4): a ranged scalar's
// declared min and max, and an ORDINAL's set — a union tag past the arm
// count, an enum ordinal past the enum's top value. Straight-line, after
// the copy, over STORAGE, so the identity plan and a plan compiled from a
// stranger's layout are held to the same numbers by the same pass. Every
// clamp COUNTS. The pass walks LIVE elements only: a counted array's live
// count, not its slack; an optional's payload only when present; a union's
// set arm, not the others.
func CompletionFixedClamp(value *Completion, report *TableReport) {
	clamped := int32(0)
	CompletionFixedClampBody(value, &clamped)
	report.Clamped += clamped
}

